from urllib.parse import urlparse, parse_qs, urlunparse

def apply_rewrite_rules(rules, urls):
    results = []

    for url in urls:
        parsed = urlparse(url)
        matched_rule = None

        # Try each rule in order
        for rule in rules:
            if matches_rule(parsed, rule):
                matched_rule = rule
                break

        # If no rule matches, return original URL
        if not matched_rule:
            results.append(url)
            continue

        # Apply action from matched rule
        result = apply_action(parsed, matched_rule)
        results.append(result)

    return results


def matches_rule(parsed_url, rule):
    match_type = rule['match_type']
    match_value = rule['match_value']

    if match_type == 'path_prefix':
        path = parsed_url.path
        # Strip leading slash from path for comparison if needed
        if match_value.startswith('/'):
            return path.startswith(match_value)
        else:
            # Handle non-prefixed match_value
            return '/' in (path or '') or path == '/' or path.startswith(match_value)

    elif match_type == 'host':
        host = parsed_url.hostname
        # Exact match
        if host == match_value:
            return True
        # Subdomain wildcard match (*.example.com matches sub.example.com)
        if match_value.startswith('*.'):
            base_domain = match_value[2:]
            if host and base_domain:
                if host.endswith('.' + base_domain):
                    return True
            elif base_domain == host:  # Exact match without wildcard
                return True

    elif match_type == 'query_param':
        query = parsed_url.query or ''
        if not query:
            return False
        params = parse_qs(query, keep_blank_values=True)
        return match_value in params

    return False


def apply_action(parsed_url, rule):
    action = rule['action']
    action_value = rule.get('action_value', '')

    if action == 'block':
        return None

    elif action == 'strip_prefix':
        path = parsed_url.path
        # Remove the prefix if exists
        if path.startswith(action_value):
            new_path = path[len(action_value):] or '/'
        else:
            new_path = path
        scheme, netloc, path = parsed_url.scheme, parsed_url.netloc, new_path
        return urlunparse((scheme, netloc, path, '', parsed_url.query, ''))

    elif action == 'redirect_host':
        scheme = parsed_url.scheme or 'http'
        # Preserve port if present (e.g., :8080)
        if parsed_url.port:
            new_netloc = f"{action_value}:{parsed_url.port}"
        else:
            new_netloc = action_value
        scheme, netloc, path = scheme, new_netloc, parsed_url.path
        query = parsed_url.query or ''
        fragment = parsed_url.fragment or ''
        return urlunparse((scheme, netloc, path, '', query, fragment))

    elif action == 'add_query_param':
        path = parsed_url.path
        scheme = parsed_url.scheme
        netloc = parsed_url.netloc
        params = parse_qs(parsed_url.query or '', keep_blank_values=True)

        # Parse key=value from action_value if contains '='
        if '=' in action_value:
            key, value = action_value.split('=', 1)
            params[key] = value
        else:
            params[action_value] = ''

        query_params = []
        for k in sorted(params.keys()):
            v = params[k][0] if isinstance(params[k], list) else params[k]
            if k != 'action_value':  # skip any internal param used
                query_params.append(f"{k}={v}" if v else f"{k}")

        new_query = '&'.join(query_params)
        return urlunparse((scheme, netloc, path, '', new_query, ''))

    # Fallback (shouldn't happen with well-formed rules)
    return parsed_url.geturl()
